#include <cassert>
#include <map>
#include <set>
#include "gameplay/commerce/v2/ShopTransactionService.h"
using namespace gameplay; using namespace gameplay::commerce; using namespace gameplay::inventory;
namespace {
struct State final:IWalletQuery,IWalletCommands,IInventoryQuery,IInventoryCommands,IPotionStackQuery,IPotionStackCommands,IInventoryReservationService{
 std::map<unsigned,CurrencyAmount> gold;std::map<unsigned,std::set<unsigned> > items;std::map<unsigned,PotionQuantity> potions;bool rejectDebit=false;bool rejectCredit=false;bool active=false;
 bool TryGetWallet(PlayerId p,WalletSnapshot&o)const override{auto i=gold.find(p.value);if(i==gold.end())return false;o=WalletSnapshot(p,i->second);return true;}
 WalletMutationResult Credit(PlayerId p,CurrencyAmount a,WalletReason)override{WalletMutationResult r;r.player=p;r.requested=a;auto i=gold.find(p.value);if(i==gold.end()){r.code=WalletMutationCode::PlayerNotFound;return r;}r.before=i->second;if(rejectCredit){r.after=i->second;r.code=WalletMutationCode::LegacyRejected;return r;}i->second+=a;r.after=i->second;r.code=WalletMutationCode::Ok;return r;}
 WalletMutationResult Debit(PlayerId p,CurrencyAmount a,WalletReason)override{WalletMutationResult r;r.player=p;r.requested=a;auto i=gold.find(p.value);if(i==gold.end()){r.code=WalletMutationCode::PlayerNotFound;return r;}r.before=i->second;if(rejectDebit){r.after=i->second;r.code=WalletMutationCode::LegacyRejected;return r;}if(i->second<a){r.after=i->second;r.code=WalletMutationCode::InsufficientFunds;return r;}i->second-=a;r.after=i->second;r.code=WalletMutationCode::Ok;return r;}
 InventoryPresenceResult Contains(PlayerId p,ItemInstanceId item)const override{InventoryPresenceResult r;r.player=p;r.item=item;auto i=items.find(p.value);r.code=i!=items.end()&&i->second.count(item.key)?InventoryPresenceCode::Present:InventoryPresenceCode::Absent;return r;}bool TryGetSnapshot(PlayerId,InventorySnapshot&)const override{return false;}
 InventoryMutationResult Add(PlayerId p,ItemInstanceId item)override{InventoryMutationResult r;r.player=p;r.item=item;if(items[p.value].count(item.key)){r.code=InventoryMutationCode::AlreadySatisfied;return r;}items[p.value].insert(item.key);r.code=InventoryMutationCode::Applied;return r;}InventoryMutationResult Remove(PlayerId p,ItemInstanceId item)override{InventoryMutationResult r;r.player=p;r.item=item;r.code=items[p.value].erase(item.key)?InventoryMutationCode::Applied:InventoryMutationCode::ItemNotFound;return r;}InventoryTransferResult Transfer(PlayerId,PlayerId,ItemInstanceId)override{return InventoryTransferResult();}InventoryGrantResult Grant(const ItemGrant&)override{return InventoryGrantResult();}
 bool TryGetStack(PlayerId p,ItemId potion,PotionStackSnapshot&o)const override{auto i=potions.find(p.value);if(i==potions.end())return false;o=PotionStackSnapshot(p,potion,i->second);return true;}PotionStackMutationResult AddStack(const PotionStackMutationRequest&q)override{PotionStackMutationResult r;r.request=q;r.before=potions[q.player.value];potions[q.player.value]+=q.quantity;r.after=potions[q.player.value];r.code=PotionStackMutationCode::Applied;return r;}PotionStackMutationResult RemoveStack(const PotionStackMutationRequest&q)override{PotionStackMutationResult r;r.request=q;r.before=potions[q.player.value];if(r.before<q.quantity){r.after=r.before;r.code=PotionStackMutationCode::InsufficientQuantity;return r;}potions[q.player.value]-=q.quantity;r.after=potions[q.player.value];r.code=PotionStackMutationCode::Applied;return r;}PotionStackTransferResult TransferStack(const PotionStackTransferRequest&)override{return PotionStackTransferResult();}
 InventoryReservationResult Reserve(const InventoryReservationRequest&q)override{InventoryReservationResult r;if(q.items.empty())return r;active=true;r.code=InventoryReservationCode::Reserved;r.token=InventoryReservationToken(1);return r;}bool Release(InventoryReservationToken t)override{if(active&&t.Valid()){active=false;return true;}return false;}std::size_t ReleasePlayer(PlayerId)override{return 0;}bool IsReserved(PlayerId,ItemInstanceId)const override{return active;}
};}
int main(){State s;s.gold[1]=1000;s.potions[1]=5;ShopTransactionService svc(s,s,s,s,s,s,s);ItemInstanceId sword(ItemId(10),77,88);
 auto buy=svc.PurchaseItem(ShopItemPurchaseRequest(PlayerId(1),sword,200));assert(buy.Purchased());assert(s.gold[1]==800&&s.items[1].count(77));
 // Wallet rejection after item grant must remove the granted item.
 ItemInstanceId shield(ItemId(11),78,89);s.rejectDebit=true;auto bad=svc.PurchaseItem(ShopItemPurchaseRequest(PlayerId(1),shield,100));assert(bad.code==ShopItemPurchaseCode::WalletRejected);assert(!s.items[1].count(78));s.rejectDebit=false;
 // Sale wallet rejection must restore the removed item and release reservation.
 s.rejectCredit=true;auto sale=svc.SellItem(ShopItemSaleRequest(PlayerId(1),sword,125));assert(sale.code==ShopItemSaleCode::WalletRejected);assert(s.items[1].count(77));assert(!s.active);s.rejectCredit=false;
 auto potion=svc.PurchasePotion(ShopPotionPurchaseRequest(PlayerId(1),ItemId(20),10,3));assert(potion.Purchased());assert(s.potions[1]==8);
 return 0;}
